<?php declare(strict_types=1);namespace StudPulse\Http;use StudPulse\Bars\BarsClient;use StudPulse\Config;use StudPulse\Integrations\{MpeiMailbox,MpeiMailConnections};use StudPulse\Database\DB;use StudPulse\Security\{Auth,Crypto,LoginPassword,RateLimit};final class BarsAuthController{private static function cookie(string$value,int$expires):void{setcookie('sp_bars_flow',$value,['expires'=>$expires,'path'=>'/api/v1/auth/bars','secure'=>!Config::local(),'httponly'=>true,'samesite'=>'Strict']);}public function handle(#[\SensitiveParameter]Request$r,string$action):array{Auth::origin($r);if(Config::get('BARS_PROVIDER_MODE')!=='official'){throw new ApiError(503,'BARS_DISABLED','Вход через МЭИ отключён в настройках сервера.');}if($action==='login'){return$this->login($r);}$token=$r->body['flowToken']??'';$browser=$_COOKIE['sp_bars_flow']??'';if(!is_string($token)||!preg_match('/^[A-Za-z0-9_-]{43}$/D',$token)||!is_string($browser)||!preg_match('/^[A-Za-z0-9_-]{43}$/D',$browser)){throw new ApiError(410,'BARS_FLOW_EXPIRED','Начните вход заново.');}RateLimit::check('bars-flow:'.$token.':'.$action,$action==='code'?5:20,600);$result=DB::transaction(function()use($r,$action,$token,$browser):array|ApiError{$flow=DB::one('SELECT * FROM bars_auth_flows WHERE token_hash=? AND browser_hash=? AND expires_at>UTC_TIMESTAMP(6) FOR UPDATE',[Crypto::hash($token),Crypto::hash($browser)]);if(!$flow){throw new ApiError(410,'BARS_FLOW_EXPIRED','Время входа истекло. Введите логин и пароль ещё раз.');}if($action==='cancel'){DB::run('DELETE FROM bars_auth_flows WHERE token_hash=?',[Crypto::hash($token)]);self::cookie('',time()-3600);return['cancelled'=>true];}$state=json_decode(Crypto::decrypt($flow['ciphertext']),true,32,JSON_THROW_ON_ERROR);if(!isset($state['passwordHash'],$state['loginKey'])){throw new ApiError(410,'BARS_FLOW_EXPIRED','Форма входа обновилась. Введите логин и пароль ещё раз.');}$client=new BarsClient($state['cookies']);try{if($action==='send-code'&&$state['stage']==='two_factor'){$provider=$r->body['provider']??'';if(!is_string($provider)||!in_array($provider,array_column($state['providers'],'id'),true)){throw new ApiError(422,'BARS_PROVIDER','Выберите доступный способ получения кода.');}if(($state['resendAt']??0)>time()){throw new ApiError(429,'BARS_CODE_COOLDOWN','Подождите перед повторной отправкой кода.',['retryAfter'=>$state['resendAt']-time()]);}$this->sendCode($state,$client,$provider,$token);}elseif($action==='code'&&$state['stage']==='two_factor'){$code=$r->body['code']??'';if(!is_string($code)||!preg_match('/^[0-9]{4,12}$/D',trim($code))){throw new ApiError(422,'VALIDATION','Введите код подтверждения.');}$state['profiles']=$client->submitCode($state['login'],trim($code));$state['stage']='profiles';if(count($state['profiles'])===1){$result=$this->finish($state['profiles'][0],$client->cookies(),$state);DB::run('DELETE FROM bars_auth_flows WHERE token_hash=?',[Crypto::hash($token)]);self::cookie('',time()-3600);return$result;}}elseif($action==='profile'&&$state['stage']==='profiles'){$id=$r->body['studentId']??'';$selected=null;if(is_string($id)&&in_array($id,array_column($state['profiles'],'id'),true)){foreach($client->profiles()as$profile){if($profile['id']===$id){$selected=$profile;break;}}}if(!$selected){throw new ApiError(403,'BARS_PROFILE','Профиль недоступен в этой учётной записи.');}$result=$this->finish($selected,$client->cookies(),$state);DB::run('DELETE FROM bars_auth_flows WHERE token_hash=?',[Crypto::hash($token)]);self::cookie('',time()-3600);return$result;}else{throw new ApiError(409,'BARS_FLOW_STAGE','Шаг входа уже изменился. Начните вход заново.');}$error=null;}catch(ApiError$e){$error=$e;}$state['cookies']=$client->cookies();DB::run('UPDATE bars_auth_flows SET ciphertext=? WHERE token_hash=?',[Crypto::encrypt(json_encode($state,JSON_THROW_ON_ERROR)),Crypto::hash($token)]);return$error??$this->view($state,$token);});if($result instanceof ApiError){throw$result;}return$result;}private function login(#[\SensitiveParameter]Request$r):array{$login=$r->body['login']??'';$password=$r->body['password']??'';if(!is_string($login)||!preg_match('/^[a-zA-Z0-9._-]{1,100}$/D',trim($login))||!is_string($password)||$password===''||strlen($password)>1024){throw new ApiError(422,'VALIDATION','Введите имя абонента и пароль МЭИ.');}$login=trim($login);RateLimit::check('bars-login-ip:'.($_SERVER['REMOTE_ADDR']??''),10,900);RateLimit::check('bars-login-account:'.strtolower($login),5,900);$key=LoginPassword::key($login);$remember=($r->body['remember']??true)===true;$account=DB::one('SELECT * FROM bars_accounts WHERE login_key=?',[$key]);$passwordMatched=$account&&LoginPassword::verify($password,$account['password_hash']);if($passwordMatched&&($r->body['forceBars']??false)!==true){$restored=$this->restore($account,$remember,$password);if($restored!==null){return$restored;}}$client=new BarsClient();$stage=$client->login($login,$password);$state=array_merge($stage,['login'=>$login,'loginKey'=>$key,'passwordHash'=>LoginPassword::hash($password),'previousPasswordMatched'=>(bool)$passwordMatched,'remember'=>$remember]);if(MpeiMailbox::available())$state['mailPassword']=$password;if($state['stage']==='profiles'&&count($state['profiles'])===1){return DB::transaction(function()use($state,$client):array{$result=$this->finish($state['profiles'][0],$client->cookies(),$state);$this->clearPending();return$result;});}$token=Crypto::token();$browser=Crypto::token();if($state['stage']==='two_factor'){if(is_string($state['provider']??null)&&$state['provider']!==''){$this->sendCode($state,$client,$state['provider'],$token);}else{$state['sendError']='Не удалось определить канал отправки кода по ответу БАРС. Повторите вход.';$state['sendErrorCode']='BARS_CHANNEL_UNKNOWN';}}$state['cookies']=$client->cookies();DB::transaction(function()use($state,$token,$browser):void{DB::run('DELETE FROM bars_auth_flows WHERE expires_at<=UTC_TIMESTAMP(6)');$old=$_COOKIE['sp_bars_flow']??'';if(is_string($old)&&$old!==''){DB::run('DELETE FROM bars_auth_flows WHERE browser_hash=?',[Crypto::hash($old)]);}DB::run('INSERT INTO bars_auth_flows(token_hash,browser_hash,ciphertext,expires_at) VALUES(?,?,?,DATE_ADD(UTC_TIMESTAMP(6), INTERVAL 10 MINUTE))',[Crypto::hash($token),Crypto::hash($browser),Crypto::encrypt(json_encode($state,JSON_THROW_ON_ERROR))]);});self::cookie($browser,time()+600);return$this->view($state,$token);}private function sendCode(array&$state,BarsClient$client,string$provider,string$token):void{$state['codeSent']=false;$state['provider']=$provider;$state['resendAt']=time()+30;unset($state['sendError'],$state['sendErrorCode']);try{RateLimit::check('bars-send:'.$token,1,30);$state['provider']=$client->sendCode($provider);$state['codeSent']=true;}catch(ApiError$e){$state['sendError']=$e->getMessage();$state['sendErrorCode']=$e->errorCode;}$state['resendAt']=time()+30;}private function restore(array$account,bool$remember,#[\SensitiveParameter]string$password):?array{$result=DB::transaction(function()use($account,$remember,$password):array|ApiError|null{$user=DB::one('SELECT * FROM users WHERE id=? FOR UPDATE',[$account['user_id']]);if(!$user||$user['status']!=='active'||$user['provider']!=='bars'){return null;}$connection=DB::one("SELECT * FROM provider_connections WHERE user_id=? AND provider='bars' FOR UPDATE",[$user['id']]);if(!$connection||$connection['connection_status']!=='connected'){return null;}$credential=DB::one('SELECT * FROM provider_credentials WHERE connection_id=? AND expires_at>UTC_TIMESTAMP(6) FOR UPDATE',[$connection['id']]);$current=DB::one('SELECT * FROM bars_accounts WHERE login_key=? FOR UPDATE',[$account['login_key']]);if(!$credential||!$current||$current['user_id']!==$user['id']||!hash_equals($account['password_hash'],$current['password_hash'])){return null;}$data=json_decode(Crypto::decrypt($credential['ciphertext']),true,32,JSON_THROW_ON_ERROR);if(($data['loginKey']??'')!==$account['login_key']){return null;}$client=new BarsClient($data['cookies']);try{$profile=null;foreach($client->profiles()as$candidate){if($candidate['id']===$user['external_subject']){$profile=$candidate;break;}}if(!$profile){throw new ApiError(401,'BARS_LOGIN_REQUIRED','Сохранённая сессия БАРС больше не подходит для этого профиля.');}}catch(ApiError$e){if(in_array($e->errorCode,['BARS_LOGIN_REQUIRED','BARS_NO_STUDENT'],true)){DB::run('DELETE FROM provider_credentials WHERE id=?',[$credential['id']]);DB::run("UPDATE provider_connections SET connection_status='expired' WHERE id=?",[$connection['id']]);return null;}return$e;}$state=['login'=>$current['login'],'loginKey'=>$current['login_key'],'passwordHash'=>$current['password_hash'],'previousPasswordMatched'=>true,'remember'=>$remember];if(MpeiMailbox::available())$state['mailPassword']=$password;$result=$this->finish($profile,$client->cookies(),$state);$this->clearPending();return[...$result,'restored'=>true];});if($result instanceof ApiError){throw$result;}return$result;}private function clearPending():void{$browser=$_COOKIE['sp_bars_flow']??'';if(is_string($browser)&&$browser!==''){DB::run('DELETE FROM bars_auth_flows WHERE browser_hash=?',[Crypto::hash($browser)]);}self::cookie('',time()-3600);}private function view(array$state,string$token):array{$labels=['1'=>'Telegram','2'=>'ВКонтакте','3'=>'MAX'];return['stage'=>$state['stage'],'flowToken'=>$token,'providers'=>$state['providers']??[],'provider'=>$state['provider']??null,'providerName'=>$labels[$state['provider']??'']??null,'profiles'=>$state['profiles']??[],'codeSent'=>$state['codeSent']??false,'sendError'=>$state['sendError']??null,'sendErrorCode'=>$state['sendErrorCode']??null,'resendAfter'=>max(0,($state['resendAt']??0)-time())];}private function finish(array$profile,array$cookies,#[\SensitiveParameter]array$state):array{DB::run("INSERT INTO users(id,provider,external_subject,display_name,university_verified_at) VALUES(?,'bars',?,?,UTC_TIMESTAMP(6)) ON DUPLICATE KEY UPDATE display_name=VALUES(display_name),university_verified_at=UTC_TIMESTAMP(6)",[DB::id(),$profile['id'],$profile['name']]);$user=DB::one("SELECT * FROM users WHERE provider='bars' AND external_subject=? FOR UPDATE",[$profile['id']]);if(!$user||$user['status']!=='active'){throw new ApiError(403,'ACCOUNT_DISABLED','Аккаунт недоступен.');}DB::run('INSERT IGNORE INTO user_profiles(user_id) VALUES(?)',[$user['id']]);DB::run("INSERT INTO provider_connections(id,user_id,provider,external_id,connection_status,scopes,last_verified_at) VALUES(?,?,'bars',?,'connected',?,UTC_TIMESTAMP(6)) ON DUPLICATE KEY UPDATE external_id=VALUES(external_id),connection_status='connected',scopes=VALUES(scopes),last_verified_at=UTC_TIMESTAMP(6)",[DB::id(),$user['id'],$profile['id'],json_encode(['profile:read','grades:read'])]);$connection=DB::one("SELECT id FROM provider_connections WHERE user_id=? AND provider='bars'",[$user['id']]);$expires=gmdate('Y-m-d H:i:s',time()+(int)Config::get('SESSION_DAYS','30')*86400);DB::run('INSERT INTO provider_credentials(id,connection_id,ciphertext,key_version,expires_at) VALUES(?,?,?,?,?) ON DUPLICATE KEY UPDATE ciphertext=VALUES(ciphertext),key_version=VALUES(key_version),expires_at=VALUES(expires_at)',[DB::id(),$connection['id'],Crypto::encrypt(json_encode(['cookies'=>$cookies,'profile'=>$profile,'verifiedAt'=>gmdate('c'),'loginKey'=>$state['loginKey']],JSON_THROW_ON_ERROR)),Config::get('TOKEN_KEY_ID','v1'),$expires]);$previous=DB::one('SELECT * FROM bars_accounts WHERE login_key=? FOR UPDATE',[$state['loginKey']]);if($previous&&!($state['previousPasswordMatched']??false)){DB::run('UPDATE user_sessions SET revoked_at=UTC_TIMESTAMP(6) WHERE user_id=? AND revoked_at IS NULL',[$previous['user_id']]);}DB::run('INSERT INTO bars_accounts(login_key,login,user_id,password_hash,verified_at) VALUES(?,?,?,?,UTC_TIMESTAMP(6)) ON DUPLICATE KEY UPDATE login=VALUES(login),user_id=VALUES(user_id),password_hash=VALUES(password_hash),verified_at=UTC_TIMESTAMP(6)',[$state['loginKey'],$state['login'],$user['id'],$state['passwordHash']]);$this->membership($user['id'],$profile['group']);$afterIssue=null;if(isset($state['mailPassword'])&&MpeiMailbox::available()&&MpeiMailbox::shortLogin($state['login'])!==null){$afterIssue=static function(array$session)use($state):void{try{MpeiMailConnections::store($session,$state['login'],$state['mailPassword'],true,null);}catch(\PDOException$error){error_log('StudPulse MPEI mail setup: MySQL '.(int)($error->errorInfo[1]??0));}};}return['stage'=>'authenticated','message'=>'Вход выполнен',...Auth::issue($user,$state['remember'],afterIssue:$afterIssue)];}private function membership(string$userId,string$code):void{$groups=DB::all("SELECT g.id,t.id AS term_id,t.ends_at FROM academic_groups g JOIN universities u ON u.id=g.university_id JOIN terms t ON t.university_id=g.university_id AND t.academic_year=g.academic_year WHERE u.code='mpei' AND g.canonical_code=? AND g.archived_at IS NULL AND t.archived_at IS NULL AND t.begins_at<=UTC_DATE() AND t.ends_at>=UTC_DATE()",[$code]);DB::run("UPDATE group_memberships SET valid_to=UTC_TIMESTAMP(6) WHERE user_id=? AND verified_source='bars' AND valid_to>UTC_TIMESTAMP(6)",[$userId]);DB::run('UPDATE group_memberships m JOIN academic_groups g ON g.id=m.group_id SET m.valid_to=UTC_TIMESTAMP(6) WHERE m.user_id=? AND g.canonical_code<>? AND m.valid_to>UTC_TIMESTAMP(6)',[$userId,$code]);if(count($groups)!==1){return;}$group=$groups[0];if(DB::one("SELECT id FROM group_memberships WHERE user_id=? AND group_id=? AND term_id=? AND role IN ('headman','deputy') AND valid_from<=UTC_TIMESTAMP(6) AND valid_to>UTC_TIMESTAMP(6)",[$userId,$group['id'],$group['term_id']])){return;}DB::run("INSERT INTO group_memberships(id,group_id,user_id,term_id,role,verified_source,verified_at,valid_from,valid_to) VALUES(?,?,?,?,'student','bars',UTC_TIMESTAMP(6),UTC_TIMESTAMP(6),LEAST(DATE_ADD(UTC_TIMESTAMP(6),INTERVAL 7 DAY),DATE_ADD(?,INTERVAL 1 DAY)))",[DB::id(),$group['id'],$userId,$group['term_id'],$group['ends_at']]);}}